/**
 * Real Italy boundaries: ISTAT administrative limits via
 * openpolis/geojson-italy (CC-BY 4.0), simplified with mapshaper
 * (Visvalingam, topology-preserving) and quantized to 3 decimals.
 * Provinces aggregated to regions; Trento (021) and Bolzano (022)
 * kept separate to match region ids 21/22 in ~/lib/regions.ts.
 *
 * Coordinate order is [lon, lat]. Each region holds all its exterior
 * rings (mainland + islands) so shared borders stay gap-free.
 */

export interface RegionPoly {
  id: number;
  short: string;
  /** exterior rings in [lon, lat]. */
  rings: Array<Array<[number, number]>>;
  /** label anchor [lon, lat]. */
  label: [number, number];
}

/** Projection bounds — shared by SVG base and the three.js overlay. */
export const MAP_BOUNDS = {
  minLon: 6.6,
  maxLon: 18.6,
  minLat: 35.4,
  maxLat: 47.1,
};

export const VIEW_W = 360;
export const VIEW_H = 440;

/** Equirectangular fit of lon/lat into the SVG viewBox. */
export function project(
  lon: number,
  lat: number,
  w = VIEW_W,
  h = VIEW_H,
): [number, number] {
  const x =
    ((lon - MAP_BOUNDS.minLon) / (MAP_BOUNDS.maxLon - MAP_BOUNDS.minLon)) * w;
  const y =
    ((MAP_BOUNDS.maxLat - lat) / (MAP_BOUNDS.maxLat - MAP_BOUNDS.minLat)) * h;
  return [x, y];
}

/** All rings of a region as one SVG path (multiple M…Z subpaths). */
export function ringsToPath(
  rings: Array<Array<[number, number]>>,
  w = VIEW_W,
  h = VIEW_H,
): string {
  return rings
    .map(
      (ring) =>
        `M${ring.map(([lo, la]) => project(lo, la, w, h).join(",")).join(" ")} Z`,
    )
    .join(" ");
}

/** Dissolved MultiPolygon (see ~/lib/map/dissolve) as one SVG path. */
export function multiToPath(
  multi: Array<Array<Array<[number, number]>>>,
  w = VIEW_W,
  h = VIEW_H,
): string {
  return multi
    .map((poly) =>
      poly
        .map(
          (ring) =>
            `M${ring.map(([lo, la]) => project(lo, la, w, h).join(",")).join(" ")} Z`,
        )
        .join(" "),
    )
    .join(" ");
}

